    @EventHandler( payloadType=CreateCategoryEvent.class )
    public void handle( CreateCategoryEvent event) {
	    LOGGER.info("handling CreateCategoryEvent - " + event );
	    Category entity = new Category();
            entity.setCategoryId( event.getCategoryId() );
            entity.setName( event.getName() );
            entity.setSlug( event.getSlug() );
            entity.setPosition( event.getPosition() );
            entity.setAsActive( event.getAsActive() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCategory( entity );
    }

