    /**
     * Method to retrieve the Category via an CategoryPrimaryKey.
     * @param 	id Long
     * @return 	Category
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Category handle( FindCategoryQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCategoryId() );
    }
    
    /**
     * Method to retrieve a collection of all Categorys
     *
     * @param	query	FindAllCategoryQuery 
     * @return 	List<Category> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Category> handle( FindAllCategoryQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCategory,
 * but only if the id matches
 *
 * @param		entity	Category
 */
	protected void emitFindCategory( Category entity ) {
		LOGGER.info("handling emitFindCategory" );
		
	    queryUpdateEmitter.emit(FindCategoryQuery.class,
	                            query -> query.getFilter().getCategoryId().equals(entity.getCategoryId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCategory
	 * 
	 * @param		entity	Category
	 */
	protected void emitFindAllCategory( Category entity ) {
		LOGGER.info("handling emitFindAllCategory" );
		
	    queryUpdateEmitter.emit(FindAllCategoryQuery.class,
	                            query -> true,
	                            entity);
	}

